-#include "os_types.h"
-#include "board.h"
-#include "os_task.h"
-#include "os_assert.h"
-
-static void user_task(void *parameter)
-{
-    int i = 0;
-
-    for (i = 0; i < led_table_size; i++)
-    {
-        os_pin_mode(led_table[i].pin, PIN_MODE_OUTPUT);
-    }
-
-    while (1)
-    {
-          for (i = 0; i < led_table_size; i++)
-          {
-              os_pin_write(led_table[i].pin, led_table[i].active_level);
-           os_task_msleep(500);
-            
-         
-              os_pin_write(led_table[i].pin, !led_table[i].active_level);
-              os_task_msleep(500);
-          }
-    }
-}
-
-
-
-int main(void)
-{
-    os_task_id task;
-
-    task = os_task_create(OS_NULL, OS_NULL, 512, "user", user_task, OS_NULL, 3);
-    OS_ASSERT(task);
-    os_task_startup(task);
-
-    return 0;
-}
